code:
import json
from gurobipy import Model, GRB, quicksum

# Problem parameters
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [20, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

# Create a new model
m = Model("MultiCommodityTransportation")

# Create variables
x = {}
for i in range(len(supply)):
    for p in range(len(supply[0])):
        for j in range(len(supply[0][0])):
            x[f"x_{i,p,j}"] = m.addVar(vtype=GRB.CONTINUOUS, name=f"x_{i,p,j}")

# Add supply constraints
for i in range(len(supply)):
    for p in range(len(supply[0])):
        m.addConstr(quicksum(x[f"x_{i,p,j}"] for j in range(len(supply[0][0]))) == supply[i][p], f"supply_{i,p}")

# Add demand constraints
for p in range(len(supply[0])):
    for j in range(len(supply[0][0])):
        m.addConstr(quicksum(x[f"x_{i,p,j}"] for i in range(len(supply))) == demand[p][j], f"demand_{p,j}")

# Add limit constraints
for i in range(len(supply)):
    for j in range(len(supply[0][0])):
        m.addConstr(quicksum(x[f"x_{i,p,j}"] for p in range(len(supply[0]))) <= limit[i][j], f"limit_{i,j}")

# Set objective
m.setObjective(quicksum(cost[i][j][p] * x[f"x_{i,p,j}"] for i in range(len(supply)) for p in range(len(supply[0])) for j in range(len(supply[0][0]))), GRB.MINIMIZE)

# Optimize the model
m.optimize()

# Print the solution
print(json.dumps({"objective_value": m.objVal, "assignment": {f"x_{i,p,j}": x[f"x_{i,p,j}"].X for i in range(len(supply)) for p in range(len(supply[0])) for j in range(len(supply[0][0]))}}))

