===CODE===
```python
import gurobipy as gp
from gurobipy import GRB

# Create a new model
m = gp.Model("transportation_problem")

# Define variables
x = {}
for i in range(m):
    for k in range(p):
        x[i, k] = m.addVar(vtype=GRB.CONTINUOUS, name=f"x[{i}, {k}]")

# Define constraints
for j in range(n):
    for k in range(p):
        m.addConstr(x[0, k] + x[1, k] + ... + x[m-1, k] <= f[k], name=f"c1[{j}, {k}]")

# Define objective
m.setObjective(sum(c[i, k] * x[i, k] for i in range(m) for k in range(p)), GRB.MINIMIZE)

# Optimize the model
m.optimize()

# Print the solution
print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))
