from gurobipy import Model, GRB, quicksum

m = Model("Volunteer Delivery Problem")

# Define variables
seasonal_volunteers = m.addVar(vtype=GRB.INTEGER, name="seasonal_volunteers")
full_time_volunteers = m.addVar(vtype=GRB.INTEGER, name="full_time_volunteers")

# Define constraints
m.addConstr(quicksum(2 * seasonal_volunteers) + quicksum(5 * full_time_volunteers) <= 200, "max_points")
m.addConstr(quicksum(1 * seasonal_volunteers) <= 0.3 * (seasonal_volunteers + full_time_volunteers), "max_seasonal_volunteers")
m.addConstr(quicksum(1 * full_time_volunteers) >= 10, "min_full_time_volunteers")

# Define objective
m.setObjective(quicksum(1 * seasonal_volunteers) + quicksum(1 * full_time_volunteers), GRB.MAXIMIZE)

# Optimize
m.optimize()

# Print solution
print(json.dumps({"objective_value": m.objVal, "assignment": {v.VarName: v.X for v in m.getVars()}}))
