from gurobipy import Model, GRB, quicksum

# Create a new model
m = Model("MagnesiumZincProblem")

# Define variables
gummy_units = m.addVar(vtype=GRB.INTEGER, name="gummy_units")
pill_units = m.addVar(vtype=GRB.INTEGER, name="pill_units")

# Add constraints
m.addConstr(quicksum([3 * gummy_units, 2 * pill_units]) <= 200, "mg_constraint")
m.addConstr(gummy_units <= 3 * pill_units, "gummy_constraint")
m.addConstr(pill_units <= 10, "pill_constraint")

# Objective: Maximize zinc intake
m.setObjective(quicksum([4 * gummy_units, 5 * pill_units]), GRB.MAXIMIZE)

# Optimize the model
m.optimize()

