from gurobipy import Model, GRB, quicksum

# Create a new model
m = Model("bottle_production")

# Define variables
glasses = m.addVar(name="glasses", vtype=GRB.INTEGER, lb=20, ub=None)
plastics = m.addVar(name="plastics", vtype=GRB.INTEGER, lb=None, ub=None)

# Define constraints
m.addConstr(quicksum([500 * glasses, 750 * plastics]) <= 250000, "water_limit")
m.addConstr(plastics >= 3 * glasses, "plastics_min")

# Define objective
m.setObjective(quicksum([1 * glasses, 1 * plastics]), GRB.MAXIMIZE)

# Optimize the model
m.optimize()

# Print the results
print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))
