from gurobipy import Model, GRB, quicksum

# Create a new model
m = Model("advertising_optimization")

# Define variables
z_ads = m.addVar(vtype=GRB.INTEGER, name="z_ads")
soorchle_ads = m.addVar(vtype=GRB.INTEGER, name="soorchle_ads")
wassa_ads = m.addVar(vtype=GRB.INTEGER, name="wassa_ads")

# Define constraints
m.addConstr(z_ads >= 50000 * 0.05, "z_ads_min")
m.addConstr(soorchle_ads <= 15 * 0.3, "soorchle_ads_max")
m.addConstr(z_ads + soorchle_ads + wassa_ads <= 10000, "z_ads_limit")
m.addConstr(z_ads + soorchle_ads + wassa_ads <= 50000, "soorchle_ads_limit")
m.addConstr(z_ads + soorchle_ads + wassa_ads <= 33333, "wassa_ads_limit")

# Define objective
m.setObjective(quicksum([z_ads, soorchle_ads, wassa_ads]), GRB.MAXIMIZE)

# Optimize the model
m.optimize()

# Print the result
print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))
