from gurobipy import Model, GRB, quicksum

# Create a new model
m = Model("InvestmentProblem")

# Define variables
x_municipal_bonds = m.addVar(vtype=GRB.CONTINUOUS, name="x_municipal_bonds")
x_CDs = m.addVar(vtype=GRB.CONTINUOUS, name="x_CDs")
x_t-bills = m.addVar(vtype=GRB.CONTINUOUS, name="x_t-bills")
x_growth_stocks = m.addVar(vtype=GRB.CONTINUOUS, name="x_growth_stocks")

# Objective function: Maximize profit
m.setObjective(quicksum([8.5 * x_municipal_bonds, 5 * x_CDs, 6.5 * x_t-bills, 13 * x_growth_stocks]), GRB.MAXIMIZE)

# Constraints
m.addConstr(x_municipal_bonds + 2 * x_CDs + 3 * x_t-bills + 4 * x_growth_stocks <= 70000, "c1")

# Solve the model
m.optimize()

# Print the results
print(json.dumps({"objective_value": m.objVal, "assignment": {v.VarName: v.X for v in m.getVars()}}))
