from gurobipy import Model, GRB, quicksum

# Create a new model
m = Model("ResourcePlan")

# Define variables
RapidResponseCrews = m.addVar(vtype=GRB.CONTINUOUS, name="RapidResponseCrews")
CommunityOutreachPopUps = m.addVar(vtype=GRB.CONTINUOUS, name="CommunityOutreachPopUps")
QualityUpgradeKits = m.addVar(vtype=GRB.CONTINUOUS, name="QualityUpgradeKits")
CustomerExperienceAmbassadors = m.addVar(vtype=GRB.CONTINUOUS, name="CustomerExperienceAmbassadors")
PreventiveMaintenanceBlitzes = m.addVar(vtype=GRB.CONTINUOUS, name="PreventiveMaintenanceBlitzes")
ReliabilityUpgradeShifts = m.addVar(vtype=GRB.CONTINUOUS, name="ReliabilityUpgradeShifts")
CrossTrainingWorkshops = m.addVar(vtype=GRB.CONTINUOUS, name="CrossTrainingWorkshops")
EmergencyStandbyUnits = m.addVar(vtype=GRB.CONTINUOUS, name="EmergencyStandbyUnits")
NeighborhoodServiceKiosks = m.addVar(vtype=GRB.CONTINUOUS, name="NeighborhoodServiceKiosks")
DigitalAdoptionCampaigns = m.addVar(vtype=GRB.CONTINUOUS, name="DigitalAdoptionCampaigns")
SmartDispatchIntegrations = m.addVar(vtype=GRB.CONTINUOUS, name="SmartDispatchIntegrations")
SafetyOverhaulNights = m.addVar(vtype=GRB.CONTINUOUS, name="SafetyOverhaulNights")
SustainabilityRetrofitRuns = m.addVar(vtype=GRB.CONTINUOUS, name="SustainabilityRetrofitRuns")
PilotStoreRefreshes = m.addVar(vtype=GRB.CONTINUOUS, name="PilotStoreRefreshes")
HolidayCoverageTeams = m.addVar(vtype=GRB.CONTINUOUS, name="HolidayCoverageTeams")
FieldAnalyticsSprints = m.addVar(vtype=GRB.CONTINUOUS, name="FieldAnalyticsSprints")
CertificationBootcamps = m.addVar(vtype=GRB.CONTINUOUS, name="CertificationBootcamps")
WarrantyAssuranceDrives = m.addVar(vtype=GRB.CONTINUOUS, name="WarrantyAssuranceDrives")
EquityPartnershipActivations = m.addVar(vtype=GRB.CONTINUOUS, name="EquityPartnershipActivations")

# Add constraints
m.addConstr(quicksum([RapidResponseCrews, CommunityOutreachPopUps] * 2.4, 1) <= 100)
m.addConstr(quicksum([CommunityOutreachPopUps, QualityUpgradeKits, CustomerExperienceAmbassadors, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, DigitalAdoptionCampaigns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 2.15, 1) <= 100)
m.addConstr(quicksum([QualityUpgradeKits, CustomerExperienceAmbassadors, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, DigitalAdoptionCampaigns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 6.06, 1) <= 100)
m.addConstr(quicksum([CustomerExperienceAmbassadors, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, DigitalAdoptionCampaigns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 9.83, 1) <= 100)
m.addConstr(quicksum([PreventiveMaintenanceBlitzes, DigitalAdoptionCampaigns, SafetyOverhaulNights, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 5.07, 1) <= 100)
m.addConstr(quicksum([DigitalAdoptionCampaigns, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 3.37, 1) <= 100)
m.addConstr(quicksum([SafetyOverhaulNights, DigitalAdoptionCampaigns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 2.78, 1) <= 100)
m.addConstr(quicksum([SustainabilityRetrofitRuns, DigitalAdoptionCampaigns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 5.53, 1) <= 100)
m.addConstr(quicksum([PilotStoreRefreshes, DigitalAdoptionCampaigns, SafetyOverhaulNights, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 4.29, 1) <= 100)
m.addConstr(quicksum([HolidayCoverageTeams, DigitalAdoptionCampaigns, SafetyOverhaulNights, PilotStoreRefreshes, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 6.23, 1) <= 100)
m.addConstr(quicksum([FieldAnalyticsSprints, DigitalAdoptionCampaigns, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, SustainabilityRetrofitRuns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, CertificationBootcamps, EquityPartnershipActivations] * 5.18, 1) <= 100)
m.addConstr(quicksum([CertificationBootcamps, DigitalAdoptionCampaigns, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, SustainabilityRetrofitRuns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, EquityPartnershipActivations] * 8.67, 1) <= 100)
m.addConstr(quicksum([WarrantyAssuranceDrives, DigitalAdoptionCampaigns, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, SustainabilityRetrofitRuns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, EquityPartnershipActivations] * 5.95, 1) <= 100)
m.addConstr(quicksum([EquityPartnershipActivations, DigitalAdoptionCampaigns, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, SustainabilityRetrofitRuns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, EquityPartnershipActivations] * 7.3, 1) <= 100)
m.addConstr(quicksum([FinancialControlAssurance, DigitalAdoptionCampaigns, PreventiveMaintenanceBlitzes, SafetyOverhaulNights, SustainabilityRetrofitRuns, PilotStoreRefreshes, HolidayCoverageTeams, SafetyOverhaulNights, EquityPartnershipActivations] * 5.56, 1) <= 100)

# Objective function
